import dsbmv = require( './index' );


// TESTS //

// The function returns a Float64Array...
{
	const x = new Float64Array( 10 );
	const y = new Float64Array( 10 );
	const A = new Float64Array( 55 );

	dsbmv( 'row-major', 'upper', 10, 1, 1.0, A, 2, x, 1, 1.0, y, 1  ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const x = new Float64Array( 10 );
	const y = new Float64Array( 10 );
	const A = new Float64Array( 55 );

	dsbmv( 10, 'upper', 10, 1, 1.0, A, 2, x, 1, 1.0, y, 1 ); // $ExpectError
	dsbmv( true, 'upper', 10, 1, 1.0, A, 2, x, 1, 1.0, y, 1 ); // $ExpectError
	dsbmv( false, 'upper', 10, 1, 1.0, A, 2, x, 1, 1.0, y, 1 ); // $ExpectError
	dsbmv( null, 'upper', 10, 1, 1.0, A, 2, x, 1, 1.0, y, 1 ); // $ExpectError
	dsbmv( void 0, 'upper', 10, 1, 1.0, A, 2, x, 1, 1.0, y, 1 ); // $ExpectError
	dsbmv( [], 'upper', 10, 1, 1.0, A, 2, x, 1, 1.0, y, 1 ); // $ExpectError
	dsbmv( {}, 'upper', 10, 1, 1.0, A, 2, x, 1, 1.0, y, 1 ); // $ExpectError
	dsbmv( ( x: number ): number => x, 'upper', 10, 1, 1.0, A, 2, x, 1, 1.0, y, 1 ); // $ExpectError
}

