// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float64Array( 10 );
	const y = new Float64Array( 10 );
	const A = new Float64Array( 55 );

	dsbmv(); // $ExpectError
	dsbmv( 'row-major' ); // $ExpectError
	dsbmv( 'row-major', 'upper' ); // $ExpectError
	dsbmv( 'row-major', 'upper', 10 ); // $ExpectError
	dsbmv( 'row-major', 'upper', 10, 1, 1.0 ); // $ExpectError
	dsbmv( 'row-major', 'upper', 10, 1, 1.0, A ); // $ExpectError
	dsbmv( 'row-major', 'upper', 10, 1, 1.0, A, 2, x ); // $ExpectError
	dsbmv( 'row-major', 'upper', 10, 1, 1.0, A, 2, x, 1 ); // $ExpectError
	dsbmv( 'row-major', 'upper', 10, 1, 1.0, A, 2, x, 1, 1.0 ); // $ExpectError
	dsbmv( 'row-major', 'upper', 10, 1, 1.0, A, 2, x, 1, 1.0, y ); // $ExpectError
	dsbmv( 'row-major', 'upper', 10, 1, 1.0, A, 2, x, 1, 1.0, y, 1, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a Float64Array...
{
	const x = new Float64Array( 10 );
	const y = new Float64Array( 10 );
	const A = new Float64Array( 55 );

	dsbmv.ndarray( 'upper', 10, 1, 1.0, A, 1, 2, 0, x, 1, 0, 1.0, y, 1, 0 ); // $ExpectType Float64Array
}

